import { expect, test } from "@playwright/test";

const API = process.env.E2E_API_URL ?? "http://localhost:8000";
const DOCX = "application/vnd.openxmlformats-officedocument.wordprocessingml.document";

// Synthetic, fictitious Word documents (generated by app.ingestion.docxgen).
const word = Buffer.from("", "base64");
const wordWithMacro = Buffer.from("", "base64");

test("a Word document is accepted, processed page by page; a macro-carrying one is rejected", async ({ request }) => {
  const registered = await request.post(`${API}/api/v1/auth/register`, {
    data: { email: `word-e2e-${Date.now()}@example.com`, password: "correct-horse-battery-staple", organization_name: "Word E2E" },
  });
  const account = await registered.json();
  const headers = { Authorization: `Bearer ${account.access_token}` };
  const org = account.organization_id;
  const project = await (await request.post(`${API}/api/v1/projects?organization_id=${org}&name=Word`, { headers })).json();

  const upload = await request.post(`${API}/api/v1/documents?organization_id=${org}&project_id=${project.id}`, {
    headers, multipart: { file: { name: "contrato-ficticio.docx", mimeType: DOCX, buffer: word } },
  });
  expect(upload.status()).toBe(202);
  const { document_id } = await upload.json();

  await expect.poll(async () => (await (await request.get(`${API}/api/v1/documents/${document_id}/status?organization_id=${org}`, { headers })).json()).status, { timeout: 30_000 }).toBe("COMPLETED");
  const doc = await (await request.get(`${API}/api/v1/documents/${document_id}?organization_id=${org}`, { headers })).json();
  expect(doc.pages).toBe(2);
  const download = await request.get(`${API}/api/v1/documents/${document_id}/download?organization_id=${org}`, { headers });
  expect(download.headers()["content-type"]).toBe(DOCX);

  const rejected = await request.post(`${API}/api/v1/documents?organization_id=${org}&project_id=${project.id}`, {
    headers, multipart: { file: { name: "macro.docx", mimeType: DOCX, buffer: wordWithMacro } },
  });
  expect(rejected.status()).toBe(422);
  expect((await rejected.json()).detail).toBe("ACTIVE_CONTENT_REJECTED");
});
